from datetime import datetime, timedelta

subject_expected = 'Seeking Employment Opportunities'
recipients = ['spencer.powell@gmail.com','joseharr@gmail.com','jamie-solomon@gmail.com','kat_simp@gmail.com','ma_smith@gmail.com']

gmail_access_token = gmail_access_token

now = datetime.now()
min_created = now.strftime('%Y-%m-%d')
max_created = (now + timedelta(days=1)).strftime('%Y-%m-%d')

print('time_window:', min_created, 'to', max_created)

threads = []
page_index = 0
page_limit = 20
sort_by = '-created_at'
while True:
    resp = apis.gmail.show_outbox_threads(
        access_token=gmail_access_token,
        query=subject_expected,
        attachment=True,
        min_created_at=min_created,
        max_created_at=max_created,
        page_index=page_index,
        page_limit=page_limit,
        sort_by=sort_by
    )
    print('page_index', page_index, 'got', len(resp))
    if not resp:
        break
    threads.extend(resp)
    page_index += 1
    if page_index > 20:
        break

print('total threads fetched:', len(threads))

# Filter threads matching exact subject and having recipients
matching = []
for t in threads:
    if t.get('subject') == subject_expected:
        participants = t.get('participants', [])
        part_emails = {p.get('email') for p in participants if 'email' in p}
        inter = part_emails.intersection(set(recipients))
        if inter:
            matching.append(t)

print('matching exact-subject threads:', len(matching))
# For each recipient, find most recent thread by created_at
# Parse created_at string ordering lexicographically should work for ISO
selected_by_recipient = {}
for r in recipients:
    candidates = []
    for t in matching:
        participants = t.get('participants', [])
        part_emails = {p.get('email') for p in participants if 'email' in p}
        if r in part_emails:
            candidates.append(t)
    if not candidates:
        selected_by_recipient[r] = None
        continue
    candidates.sort(key=lambda x: x.get('created_at',''), reverse=True)
    selected_by_recipient[r] = candidates[0]

for r in recipients:
    t = selected_by_recipient[r]
    print('recipient', r, 'selected_thread:', None if t is None else t.get('email_thread_id'), 'created_at:', None if t is None else t.get('created_at'))

# Now inspect each selected thread for attachments
inspection = {}
for r in recipients:
    t = selected_by_recipient[r]
    if t is None:
        inspection[r] = {'thread_id': None, 'has_resume_attachment': False, 'attachments': []}
        continue
    thread_id = t['email_thread_id']
    thread = apis.gmail.show_thread(email_thread_id=thread_id, access_token=gmail_access_token)
    # Find outgoing email(s) in thread with subject
    resume_file_name = 'resume.pdf'
    attachments_found = set()
    # In response, 'emails' includes sent emails; check both emails and drafts maybe
    for email_obj in thread.get('emails', []):
        if email_obj.get('subject') == subject_expected:
            # check recipient list includes r
            rcpts = [rc.get('email') for rc in email_obj.get('recipients', [])]
            if r in rcpts:
                for att in email_obj.get('attachments', []):
                    attachments_found.add(att.get('file_name'))
    # Also check drafts just in case (unlikely)
    for draft in thread.get('drafts', []):
        if draft.get('subject') == subject_expected:
            rcpts = [rc.get('email') for rc in draft.get('recipients', [])]
            if r in rcpts:
                for att in draft.get('attachments', []):
                    attachments_found.add(att.get('file_name'))

    inspection[r] = {
        'thread_id': thread_id,
        'has_resume_attachment': (resume_file_name in attachments_found),
        'attachments': sorted(list(attachments_found))
    }

for r in recipients:
    print('inspection', r, inspection[r])

